// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(receiver != address(0) && receiver.code.length == 0);
        vm.assume(receiver != address(c) && receiver != address(this));

        vm.deal(address(c), amount);
        uint256 before = receiver.balance;

        c.sendTo(receiver, amount); // caller is test contract == c's owner

        assertTrue(receiver.balance == before + amount);
    }
}
